class MKAverage {
private:
    int m, k;
    queue<int> q;
    static const int MAX_VAL = 100000;
    long long bitCount[MAX_VAL + 1];
    long long bitSum[MAX_VAL + 1];

    void update(long long bit[], int i, long long delta) {
        for (; i <= MAX_VAL; i += i & (-i)) bit[i] += delta;
    }

    long long query(long long bit[], int i) {
        long long res = 0;
        for (; i > 0; i -= i & (-i)) res += bit[i];
        return res;
    }

    int findByRank(long long rank) {
        int idx = 0;
        for (int step = 65536; step > 0; step >>= 1) {
            int nxt = idx + step;
            if (nxt <= MAX_VAL && bitCount[nxt] < rank) {
                rank -= bitCount[nxt];
                idx = nxt;
            }
        }
        return idx + 1;
    }

    long long getSmallestKSum(int count) {
        if (count == 0) return 0;
        int val = findByRank(count);
        long long cntBefore = query(bitCount, val - 1);
        long long sumBefore = query(bitSum, val - 1);
        return sumBefore + (count - cntBefore) * val;
    }

public:
    MKAverage(int m, int k) : m(m), k(k) {
        memset(bitCount, 0, sizeof(bitCount));
        memset(bitSum, 0, sizeof(bitSum));
    }

    void addElement(int num) {
        q.push(num);
        update(bitCount, num, 1);
        update(bitSum, num, num);
        if (q.size() > m) {
            int old = q.front();
            q.pop();
            update(bitCount, old, -1);
            update(bitSum, old, -old);
        }
    }

    int calculateMKAverage() {
        if (q.size() < m) return -1;
        long long totalSum = query(bitSum, MAX_VAL);
        long long smallestK = getSmallestKSum(k);
        long long largestK = totalSum - getSmallestKSum(m - k);
        long long midSum = totalSum - smallestK - largestK;
        return midSum / (m - 2 * k);
    }
};

class MKAverage {
    private int m, k;
    private Queue<Integer> q = new ArrayDeque<>();
    private static final int MAX_VAL = 100000;
    private long[] bitCount = new long[MAX_VAL + 1];
    private long[] bitSum = new long[MAX_VAL + 1];

    private void update(long[] bit, int i, long delta) {
        for (; i <= MAX_VAL; i += i & (-i)) bit[i] += delta;
    }

    private long query(long[] bit, int i) {
        long res = 0;
        for (; i > 0; i -= i & (-i)) res += bit[i];
        return res;
    }

    private int findByRank(long rank) {
        int idx = 0;
        for (int step = 65536; step > 0; step >>= 1) {
            int nxt = idx + step;
            if (nxt <= MAX_VAL && bitCount[nxt] < rank) {
                rank -= bitCount[nxt];
                idx = nxt;
            }
        }
        return idx + 1;
    }

    private long getSmallestKSum(int count) {
        if (count == 0) return 0;
        int val = findByRank(count);
        long cntBefore = query(bitCount, val - 1);
        long sumBefore = query(bitSum, val - 1);
        return sumBefore + (count - cntBefore) * val;
    }

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
    }

    public void addElement(int num) {
        q.offer(num);
        update(bitCount, num, 1);
        update(bitSum, num, num);
        if (q.size() > m) {
            int old = q.poll();
            update(bitCount, old, -1);
            update(bitSum, old, -old);
        }
    }

    public int calculateMKAverage() {
        if (q.size() < m) return -1;
        long totalSum = query(bitSum, MAX_VAL);
        long smallestK = getSmallestKSum(k);
        long largestK = totalSum - getSmallestKSum(m - k);
        long midSum = totalSum - smallestK - largestK;
        return (int)(midSum / (m - 2 * k));
    }
}

class MKAverage {
  constructor(m, k) {
    this.m = m;
    this.k = k;
    this.q = [];
    this.head = 0;
    this.MAX_VAL = 100000;
    this.bitCount = new Float64Array(this.MAX_VAL + 1);
    this.bitSum = new Float64Array(this.MAX_VAL + 1);
  }

  update(bit, i, delta) {
    for (; i <= this.MAX_VAL; i += i & -i) bit[i] += delta;
  }

  query(bit, i) {
    let res = 0;
    for (; i > 0; i -= i & -i) res += bit[i];
    return res;
  }

  findByRank(rank) {
    let idx = 0;
    for (let step = 65536; step > 0; step >>= 1) {
      const nxt = idx + step;
      if (nxt <= this.MAX_VAL && this.bitCount[nxt] < rank) {
        rank -= this.bitCount[nxt];
        idx = nxt;
      }
    }
    return idx + 1;
  }

  getSmallestKSum(count) {
    if (count === 0) return 0;
    const val = this.findByRank(count);
    const cntBefore = this.query(this.bitCount, val - 1);
    const sumBefore = this.query(this.bitSum, val - 1);
    return sumBefore + (count - cntBefore) * val;
  }

  addElement(num) {
    this.q.push(num);
    this.update(this.bitCount, num, 1);
    this.update(this.bitSum, num, num);
    if (this.q.length - this.head > this.m) {
      const old = this.q[this.head++];
      this.update(this.bitCount, old, -1);
      this.update(this.bitSum, old, -old);
    }
  }

  calculateMKAverage() {
    if (this.q.length - this.head < this.m) return -1;
    const totalSum = this.query(this.bitSum, this.MAX_VAL);
    const smallestK = this.getSmallestKSum(this.k);
    const largestK = totalSum - this.getSmallestKSum(this.m - this.k);
    const midSum = totalSum - smallestK - largestK;
    return Math.floor(midSum / (this.m - 2 * this.k));
  }
}
